select is(public.get_project_discipline_removal_impact(pg_temp.org(),pg_temp.project(),'mec')- 'canDeletePermanently','{"name":"Mechanical","engineerCount":1,"documentCount":1,"invitationCount":1,"plannedPositions":2}'::jsonb,'impact counts scope, work, invitations and planned positions');
