set local role authenticated;
select is((public.get_project_discipline_removal_impact(pg_temp.org(),pg_temp.project(),'HVAC')->>'canDeletePermanently')::boolean,true,'unrelated Mechanical history does not block unused HVAC');
select lives_ok($$select public.upsert_project_resource_plan(pg_temp.org(),pg_temp.project(),'HVAC',2,'Unfilled plan')$$,'PM can plan unused discipline');
