select is((public.get_project_discipline_removal_impact(pg_temp.org(),pg_temp.project(),'Prior assignment')->>'canDeletePermanently')::boolean,false,'past assignment audit blocks permanent deletion');
select is((public.get_project_discipline_removal_impact(pg_temp.org(),pg_temp.project(),'Request-only')->>'canDeletePermanently')::boolean,false,'pending request blocks deletion without a registered document');
select is((public.get_project_discipline_removal_impact(pg_temp.org(),pg_temp.project(),'Invitation-only')->>'canDeletePermanently')::boolean,false,'invitation blocks deletion before engineer acceptance');
select throws_ok($$select public.delete_unused_project_discipline(pg_temp.org(),pg_temp.project(),'Archived-only',true)$$,'40001',null,'server protects archived documents');
select throws_ok($$select public.delete_unused_project_discipline(pg_temp.org(),pg_temp.project(),'Prior assignment',true)$$,'40001',null,'server protects prior assignment history');
select throws_ok($$select public.delete_unused_project_discipline(pg_temp.org(),pg_temp.project(),'Request-only',true)$$,'40001',null,'server protects pending requests');
select throws_ok($$select public.delete_unused_project_discipline(pg_temp.org(),pg_temp.project(),'Invitation-only',true)$$,'40001',null,'server protects invitations created since warning was read');
